let period='week', reportTab='daily', memberTab='all', attSession='Office hours', attOverride=false, attFilter='all', learnTab='Resource', setTab='Office', structView='Tree', goalScope='office', goalFilter='all', selectedDate=today(), aiUses=+(localStorage.getItem('aiUses')||0);
const stages=['New','Contacted','Interested','Presented','Following up'];
const QUOTES={
purpose:[
"Your WHY is not a sentence you write once and forget. It is the reason you get up on the days when nobody is clapping, the picture of the life you are building when the work feels slow, and the promise you made to the people counting on you. When the reason is clear and personal, quitting stops looking like an option and starting again becomes a daily habit.",
"A dream becomes a direction the day you attach daily action to it. Write your reasons where you can see them, read them when your energy is low, and let them argue with every excuse. The person who remembers why they started will always find a way to take one more step.",
"Motivation may start the engine, but purpose is what keeps the journey going when the road is rough. Do not wait to feel inspired before you act. Act because your family, your future and your own word are worth more than a passing mood.",
"Every strong business is built twice: first in the mind of the person who believes it is possible, and then in the daily work that proves it. Guard the first building carefully, because when belief is settled, discipline becomes easier to choose.",
"The life you want will not be handed to you in one big moment. It will be assembled quietly, one honest day at a time, by the choices nobody applauds and the follow ups nobody sees. Stay faithful to the small work. It is adding up.",
"When you know who you are doing this for, rejection loses its power over you. A person can say no to an opportunity, but they cannot cancel your reason. Keep your WHY in front of you and let it pull you through the days your feelings want to negotiate."],
consistency:[
"Success in this business rarely belongs to the person who had one powerful week. It belongs to the person who kept showing up in ordinary weeks, marked present, made the calls, attended the training and refused to disappear. Consistency looks quiet while it is happening, but over time it becomes the loudest result in the room.",
"Attendance is more than being counted in a room. It is how a leader trains their own mind to be dependable. The team may forget what you said in a single meeting, but they will copy what you repeatedly do. Show up often enough and your presence becomes part of your credibility.",
"Do not measure your seriousness by how excited you feel on your best day. Measure it by what you still do on the slow day, the rainy day and the day nobody noticed your effort. Those are the days that separate a temporary interest from a real decision.",
"A streak is built one honest mark at a time. Missed a day? Do not miss the lesson. Return quickly, learn what interrupted you, and protect tomorrow. The goal is not perfection. The goal is a pattern your future self can trust.",
"People rise to the level of the habits they repeat when it is inconvenient. If you want a stronger team, first become the example of the standard. Be early, be present, be prepared, and let your consistency make leadership easier for everyone watching."],
prospecting:[
"A follow up is not pressure. Done with care, it is proof that you remembered somebody and believed their life could be better. Many people do not need a louder presentation; they need a respectful reminder, a clear answer and enough patience from you to make a decision without feeling chased.",
"Every prospect on your list represents a home, a hope, a bill, a dream or a quiet frustration they may not say out loud. Speak to the person, not only to the sale. When people feel understood, they listen longer, trust deeper and decide with less fear.",
"Silence from a prospect does not always mean no. Sometimes it means busy, afraid, confused or waiting for the courage to ask one more question. Follow up with value, keep your tone light, and leave the door open. Persistence with respect builds the kind of business that lasts.",
"Your next breakthrough may already be sitting in an old conversation. Go back kindly, remind them what attracted them at first, and ask what has changed since then. The fortune is often not in finding more people. It is in caring better for the people already within reach.",
"Do not judge a seed on the first day you plant it. Some people join quickly, some watch you for months to see whether you are consistent and real. Keep growing in public, keep serving in private, and let time turn careful follow up into trust."],
earnings:[
"Money follows value, and value is built in conversations, service, follow up and trust. Do not chase the leaderboard so hard that you forget the people behind the numbers. Serve well, record honestly, and let your earnings become evidence that your work helped somebody take a step.",
"A leaderboard is not only a ranking. It is a mirror of activity. Behind every amount is a call returned, a fear answered, a presentation completed or a customer cared for. If you want a better position, do not stare at the table. Increase the useful actions that create it.",
"Small earnings recorded faithfully matter. They teach your mind that progress is real, even before it is large. Celebrate the honest step, study what produced it, and repeat it with more skill. Big results are usually small results that refused to stop multiplying.",
"Let other people success on this board instruct you, not intimidate you. Ask what they did, how often they did it and whom they served. Then return to your own list and work your own plan. Comparison wastes energy; learning turns it into fuel."],
goals:[
"A goal is a promise written in numbers. It tells your day where to go before distractions choose for you. Break the big target into today call, today follow up and today learning, then protect those small appointments with yourself. What gets scheduled and measured rarely stays a wish.",
"You do not rise to the size of your ambition. You grow to the strength of the system you repeat. Set the target, choose the daily actions, review your progress without excuses, and adjust early. A measured goal can be rescued long before the month is over.",
"Progress loves visibility. When a team can see who has started, who is moving and who needs encouragement, nobody has to struggle in silence. Set your goal openly, update it honestly, and let accountability become support rather than shame.",
"If the goal matters, give it a deadline and a daily portion. A distant target can feel heavy, but today share is always possible. Win today share often enough and the month will take care of itself.",
"Finishing a goal begins with refusing to hide from the number. Look at where you are, name what is missing, and choose the next action while there is still time. Honest tracking is not failure. It is leadership over your own result."],
teamwork:[
"A team becomes strong when success stops being a private competition and becomes a shared standard. Teach what you learn, celebrate who is rising, answer the person who is struggling, and remember that somebody future breakthrough may begin with the encouragement you give today.",
"Nobody builds a lasting network alone. Every name in a structure represents a relationship that must be served, trained and believed in. Grow people with patience, correct them with kindness, and lead in a way that makes others want to bring their best people closer.",
"The best leaders multiply confidence. They notice effort before it becomes a result, they make the next step clear, and they remind people of who they are becoming. Build that kind of culture and your team will not only grow in number. It will grow in strength.",
"Your network will reflect the standard you protect and the care you repeat. Communicate clearly, show up consistently, train patiently and follow through. People may join because of an opportunity, but they stay because of the community they experience.",
"A rising person lifts the belief of everyone connected to them. That is why celebration matters, why training matters and why no honest effort in a team is ever only personal. When one person grows, the whole structure receives fresh proof that growth is possible."],
celebration:[
"A step up is never only a new title. It is evidence of calls made when nobody was watching, lessons applied after training, rejection survived without quitting, and a person deciding to become more. Celebrate it loudly, because what a team honours, a team repeats.",
"Recognition turns private discipline into public belief. When we pause to congratulate somebody, we are telling every new member that growth is noticed here and effort has a future here. Never rush past a victory that can strengthen the faith of the whole team.",
"Behind every rank is a story of becoming. Somebody learned a skill, served more people, faced a fear or led with greater responsibility. Honour the story, not just the badge, and let it remind you that your own next level is built the same way: one faithful step at a time.",
"Celebrate people while they are growing, not only when they arrive. Encouragement given at the right moment can keep a future leader from giving up in a hidden season. A sincere congratulations costs little and can carry somebody further than you may ever know."],
learning:[
"Training is where confidence is built before the conversation happens. Learn the product, understand people, practise your words, and apply one lesson quickly while it is still fresh. Knowledge that stays in a notebook does not change income. Knowledge put into action changes everything.",
"A teachable person is never truly stuck. They may need a better skill, a clearer example or more guided practice, but they keep their mind open long enough for growth to reach them. Protect your teachability. It is one of the fastest ways to become valuable to a team.",
"Do not attend class only to be marked present. Come with a question, leave with a decision, and teach what you learned to somebody else within days. Teaching locks learning in your memory and turns one training session into growth for many people.",
"Every leader was once a beginner who stayed in the room long enough to understand. If a lesson feels difficult, that is not proof you do not belong. It may be proof you are standing at the exact place where your next level is being formed.",
"Your skill is an asset your team can borrow through your example. Read, listen, rehearse, ask questions and improve the way you invite, present and follow up. The more competent you become, the more confidence people will place in your guidance."],
mindset:[
"A strong mind is not built by avoiding pressure. It is built by interpreting pressure correctly. A challenge can become proof that you are incapable, or training that is preparing you for greater responsibility. Choose the interpretation that makes you wiser, steadier and harder to discourage.",
"Food for the heart matters because a hungry mind will feed on fear, comparison and yesterday disappointment. Feed it daily with truth, gratitude, courage and the voices of people who are growing. What enters your mind repeatedly will eventually direct your actions.",
"You cannot control every result, but you can govern your response. Pause before reacting, remember your purpose, and choose the next useful action. That small space between a setback and your response is where personal leadership is born.",
"Confidence is not pretending you have no weakness. It is deciding that weakness will not have the final word. Train the weak area, ask for help, and keep evidence of every small win. Over time, your mind begins to trust the person you are becoming.",
"Guard your inner conversation. The voice you listen to in private becomes the courage or fear you carry into public. Speak to yourself like a leader developing a valuable person, because that is exactly what you are."],
stewardship:[
"Office money deserves clear records and clean hands. Every collection and every spending entry protects trust between leaders and members. Record promptly, explain honestly, and remember that people give more confidently when they can see that what was gathered is handled with care.",
"Stewardship is leadership in its quiet form. It is counting correctly when nobody is checking, spending wisely when nobody would notice, and keeping the record open because the team trust matters. Money handled well supports training, community and growth without suspicion.",
"Small amounts handled carelessly can damage big confidence. Keep the balance clear, separate what was collected from what was spent, and settle questions early with facts. A trusted record is not only good accounting. It is good leadership.",
"Dues are not just payments. They are members investing in a place where they learn, meet, grow and belong. Honour that investment by using it purposefully and recording it faithfully, so every contributor can respect both the mission and the management."],
leadership:[
"Leadership is not the loudest voice in the office. It is the clearest example, the most consistent presence and the person who takes responsibility before taking credit. Set the standard in your own attendance, learning and follow up, and your instructions will carry more weight.",
"A good office culture is built by what leaders repeatedly allow, appreciate and correct. Praise effort publicly, correct problems privately, communicate expectations clearly, and keep your word in small matters. Culture is not a speech. It is the pattern people experience every week.",
"Authority may give you a title, but trust gives you influence. Earn it by being fair with roles, honest with records, patient with people and firm with standards. When members believe leadership is clean and consistent, they bring more of themselves to the mission.",
"Protect both people and standards. Too much softness lets excellence die quietly; too much hardness makes people afraid to grow. Lead with a warm heart and a clear line, and your office will become a place where people are both cared for and called higher."],
discipline:[
"Your day does not need to be perfect to be powerful. It needs a clear purpose, a few right priorities and the discipline to return when you are interrupted. Tick one honest task at a time, and let completed small promises rebuild trust in yourself.",
"Discipline is choosing the future you declared over the comfort you presently feel. It is making the call, writing the list, attending the class and following up before the day closes. Feelings are real, but they are not always fit to lead.",
"A checklist is a leadership tool for your own life. It takes the noise in your mind and turns it into visible steps. Do not carry everything in your head. Write it, order it, complete it, and end the day knowing exactly what moved.",
"Rest is part of discipline, and so is starting again. Do not punish yourself for a broken day until you lose the next one too. Review honestly, forgive quickly, prepare tomorrow, and step back into the work with a clean mind.",
"The person who plans the day in alignment with their WHY will waste less time defending distractions. Decide what matters before the phone decides for you. Protect the first action, and momentum will help you finish the rest."]};
function quoteHash(s){let h=0;for(const c of s)h=(h*31+c.charCodeAt(0))>>>0;return h}
function quoteFor(cat){const list=QUOTES[cat]||QUOTES.purpose;const day=Math.floor(Date.now()/864e5);const shift=(window._qShift&&window._qShift[cat])||0;return list[((day+quoteHash(cat)+shift)%list.length+list.length)%list.length]}
function quoteNext(cat){window._qShift=window._qShift||{};window._qShift[cat]=((window._qShift[cat]||0)+1);load()}
function quoteCard(cat,label){return `<div class="card quotecard"><div class="row" style="border:0;padding:0 0 8px"><span class="kicker">${esc(label||'Daily thought')}</span><button class="btn2" onclick="quoteNext('${cat}')">Another quote</button></div><div class="qmark">&ldquo;</div><p>${esc(quoteFor(cat))}</p><small>The Amazing Team</small></div>`}

