const ROLES=[['super_admin','Super Admin','Created this office. Full control. Handed over only with Transfer Super Admin.'],['admin','Admin','Full office management'],['leader','Team Leader','Helps lead a team: reports, team prospects, attendance for others'],['training_head','Training Head','Leads a training class'],['Tutor','Tutor','Teaches a training class'],['earnings_manager','Earnings Manager','Can log member earnings'],['treasurer','Treasurer','Sees and records office funds'],['member','Member','No elevated role']];
const ELEVATED=['admin','leader','training_head','Tutor','earnings_manager','treasurer'];
const roleLabel=r=>(ROLES.find(x=>x[0]===r)||['member','Member'])[1];
const myRoles=()=>{const o=(me&&me.offices||[]).find(x=>x.id==officeId);if(!o)return ['member'];return (o.roles&&o.roles.length)?o.roles:(o.role&&o.role!=='member'?[o.role]:[])};
const myRole=()=>{const o=(me&&me.offices||[]).find(x=>x.id==officeId);return o?o.role:'member'};
const can=(...rs)=>{const s=new Set(myRoles());if(s.has('super_admin'))s.add('member');return rs.some(r=>s.has(r)||(r==='member'&&!s.size))||rs.includes('member')&&myRoles().length===0};
const canManage=()=>can('super_admin','admin');
