function tab(t){const f=$('#form');if(t==='login')f.innerHTML=`<label>Email</label><input id="email" value="demo@example.com"><label>Password</label><input id="pw" type="password" value="demo1234"><p><button class="btn wide" onclick="doLogin()">Sign in</button></p>`;if(t==='create')f.innerHTML=`<label>Office name</label><input id="oname" placeholder="Amazing Team Ikeja"><label>Office address</label><input id="slug" placeholder="amazing-team-Ikeja"><label>Your name</label><input id="name"><label>Email</label><input id="email"><label>Password</label><input id="pw" type="password"><p><button class="btn wide" onclick="doCreate()">Create office, free forever</button></p>`;if(t==='join')f.innerHTML=`<label>Office address or invite code</label><input id="slug" placeholder="demo or DEMO2026"><label>Your name</label><input id="name"><label>Email</label><input id="email"><label>Password</label><input id="pw" type="password"><p><button class="btn wide" onclick="doJoin()">Join office</button></p>`}
async function doLogin(){try{await post('/api/auth/login',{email:$('#email').value,password:$('#pw').value});me=await api('/api/me');officeId=me.offices[0]&&me.offices[0].id;localStorage.setItem('officeId',officeId);renderApp()}catch(e){toast(e.message)}}
