function openModal(html){$('#sheet').innerHTML=html;$('#modal').classList.add('open')} function closeModal(){$('#modal').classList.remove('open')} function openDrawer(html){$('#drawer').innerHTML=html;$('#drawerWrap').classList.add('open')} function closeDrawer(){$('#drawerWrap').classList.remove('open')}
