async function load(){const m=$('#main');if(!m)return;try{await pages[page]()}catch(e){m.innerHTML=`<div class="card danger"><b>Something did not load.</b><p>${esc(e.message)}</p><button class="btn" onclick="load()">Try again</button></div>`}}
