 const network=Math.max((st.items||[]).length-1,0);const last30=su.items.filter(x=>{const dt=new Date(x.date||x.created||'');return isNaN(dt)?true:(Date.now()-dt.getTime())<30*864e5});const step=su.items[0];const congratulated=JSON.parse(localStorage.getItem('congratulated')||'[]');
