 const monthName=new Date().toLocaleDateString(undefined,{month:'long'});const myGoal=go2.items.find(x=>x.user_id===me.user.id);const todayTasks=cl.items.filter(x=>x.date===today());const doneTasks=todayTasks.filter(x=>x.done).length;const waiting=d.prospects&&false?0:(window._waiting||0);const needCount=att.items.length>=0?null:null;
 const checkBadge=todayTasks.length===0?'<span class="pill amber">Not started</span>':doneTasks>=todayTasks.length?'<span class="pill green">Done</span>':'<span class="pill amber">In progress</span>';
