 if(reportTab==='weekly'){const monday=new Date();monday.setDate(monday.getDate()-((monday.getDay()+6)%7));body=`<div class="card"><h3>Weekly consistency</h3><p class="muted">Working days attended this week, per member.</p><div class="twrap"><table><tr><th>Member</th><th>Mon</th><th>Tue</th><th>Wed</th><th>Thu</th><th>Fri</th><th>Rate</th></tr>${d.members.map(x=>{let cells='',count=0;for(let i=0;i<5;i++){const dt=new Date(monday);dt.setDate(monday.getDate()+i);const ds=dt.toISOString().slice(0,10);const a=d.attendance.find(z=>z.user_id===x.id&&z.date===ds);if(a&&a.status!=='absent')count++;cells+=`<td>${a?pillFor(a.status):pillFor('')}</td>`}return `<tr><td>${av(x)} ${esc(x.name)}</td>${cells}<td><b>${Math.round(count/5*100)}%</b></td></tr>`}).join('')}</table></div></div>`}
