async function saveActivities(){const d=await api('/api/settings').catch(()=>({settings:{}}));await post('/api/settings',{settings:Object.assign({},d.settings,{activities:$('#sActs').value})});toast('Activities saved')}
function openWhy(){const cur=($('#whySeed')||{}).textContent||'';const arr=cur.split('\n');openModal(`<h2 style="margin-top:0">My 20 reasons</h2><p class="muted">Write as many as you can. These are private to you.</p>${Array.from({length:20},(_,i)=>`<label>Reason ${i+1}</label><input class="whyIn" value="${esc(arr[i]||'')}">`).join('')}<p><button class="btn wide" onclick="saveWhy()">Save my reasons</button></p><button class="btn2 wide" onclick="closeModal()">Close</button>`)}
