async function checkin(){await post('/api/checkin');toast('Checked in for today');load()}
async function markAtt(id,status){await post('/api/attendance/mark',{user_id:id,status,session:attSession});toast('Marked '+status);load()}
async function addTraining(){try{await post('/api/trainings',{title:$('#tt').value,description:$('#tdesc').value,date:$('#tdate').value});toast('Class added');load()}catch(e){toast(e.message)}}
async function completeTraining(id){await post('/api/trainings/'+id+'/complete');toast('Marked completed');load()}
async function addResource(){await post('/api/resources',{title:$('#rt').value,kind:$('#rk').value,link:$('#rl').value});toast('Added to Learning Centre');load()}
async function addFund(){await post('/api/funds',{kind:$('#fk').value,user_id:$('#fu').value,amount:$('#fa').value,description:$('#fd').value});toast('Record saved');load()}
async function congrats(id){await post('/api/stepups/'+id+'/congratulate');toast('Congratulations sent');load()}
async function congratsDash(id){const c=JSON.parse(localStorage.getItem('congratulated')||'[]');if(!c.includes(id))c.push(id);localStorage.setItem('congratulated',JSON.stringify(c));congrats(id)}
async function addStep(){await post('/api/stepups',{user_id:$('#suUser').value,new_status:$('#suStatus').value,prev_status:$('#suPrev').value});toast('Step up recorded. Time to celebrate');load()}
async function undoStep(id){await post('/api/stepups/'+id+'/undo');toast('Step up removed');load()}
async function moveProspect(id,stage){await patch('/api/prospects/'+id,{stage});toast('Moved to '+stage);load()}
async function addCheck(){await post('/api/checklist',{text:$('#ct').value,date:selectedDate});toast('Task added');load()}
async function toggleCheck(id,done){await patch('/api/checklist/'+id,{done});load()}
function uploadPhoto(input){const f=input.files&&input.files[0];if(!f)return;if(!f.type.startsWith('image/'))return toast('Choose an image file');const url=URL.createObjectURL(f);const img=new Image();img.onload=async()=>{const s=256,cv=document.createElement('canvas');cv.width=s;cv.height=s;const cx=cv.getContext('2d');const side=Math.min(img.width,img.height);cx.drawImage(img,(img.width-side)/2,(img.height-side)/2,side,side,0,0,s,s);URL.revokeObjectURL(url);try{await post('/api/profile/photo',{photo:cv.toDataURL('image/jpeg',0.85)});me=await api('/api/me');toast('Picture saved');renderApp()}catch(e){toast(e.message)}};img.onerror=()=>toast('Could not read that picture');img.src=url}
async function removePhoto(){try{await post('/api/profile/photo',{photo:''});me=await api('/api/me');toast('Picture removed');renderApp()}catch(e){toast(e.message)}}
async function saveProfile(){const pf=await api('/api/profile');await post('/api/profile',{name:$('#pfName').value,phone:$('#pfPhone').value,sponsor:$('#pfSponsor').value,status:$('#pfStatus').value,why:pf.profile.why||''});me.user.name=$('#pfName').value;toast('Profile saved');renderApp()}
boot();
function rankColor(r){return({'Director':'#d6336c','Executive Manager':'#e8890c','Senior Manager':'#7048e8','Manager':'#4c6ef5','Distributor':'#0ca678','Pro':'#228be6','Newbie':'#868e96','Member':'#868e96'})[r]||'#868e96'}
function rankSoft(r){return rankColor(r)+'22'}
function toggleBranch(id){window._collapsed=window._collapsed||new Set();window._collapsed.has(id)?window._collapsed.delete(id):window._collapsed.add(id);load()}
function openPerson(id){const all=(window._struct||[]);const x=all.find(z=>z.id===id);if(!x)return;const below=(window._structKids&&window._structKids[id])||[];openDrawer(`<button class="btn2" onclick="closeDrawer()">Close</button><div style="text-align:center;padding:12px">${x.photo?av(x,"big"):`<span class="avatar big" style="background:${rankSoft(x.status)};color:${rankColor(x.status)}">${initials(x.name)}</span>`}<h2>${esc(x.name)}</h2><span class="rankbadge" style="background:${rankColor(x.status)}">${esc(x.status||'Member')}</span> <span class="pill">${esc(x.location||'Lagos')}</span><p class="muted">${below.length} people directly below. Sponsor: ${esc(x.sponsor||'Top of this office')}</p></div><p><button class="btn wide" onclick="closeDrawer();openAddPerson(false,'${esc(x.name)}')">Add a person below them</button></p><p><button class="btn2 wide" onclick="closeDrawer();go('goals')">See team goals</button></p>`)}
function openChart(){const root=window._structRoot;if(!root){toast('Add people first');return}const zoom=window._chartZoom||0.82;const counts=window._rankCounts||{};const kids=window._structKids||{};
 const node=x=>{const ch=kids[x.id]||[];return `<div class="orgnode"><div class="orgcard">${x.photo?av(x):`<span class="avatar" style="background:${rankSoft(x.status)};color:${rankColor(x.status)}">${initials(x.name)}</span>`}<div class="orgname">${esc(x.name)}</div><span class="rankbadge" style="background:${rankColor(x.status)}">${esc(x.status||'Member')}</span> <small class="muted">${esc(x.location||'Lagos')}</small></div>${ch.length?`<div class="orgline"></div><div class="orgkids">${ch.map(node).join('')}</div>`:''}</div>`};
 const legend=Object.entries(counts).map(([r,n])=>`<span class="pill" style="margin-right:6px"><span class="stageDot" style="background:${rankColor(r)}"></span>${esc(r)} ${n}</span>`).join('');
 const ov=document.createElement('div');ov.className='chartOverlay';ov.id='chartOverlay';ov.innerHTML=`<div class="chartTop"><div><b>My team structure, ${new Date().toLocaleDateString(undefined,{month:'long',year:'numeric'})}</b><div style="margin-top:8px"><b>${(window._structBelow||[]).length}</b> <span class="muted">in the team</span> <span style="margin-left:12px">${legend}</span></div><div class="tabs" style="margin:12px 0 0"><button class="btn2" onclick="setZoom(-0.1)">Minus</button><b style="padding:8px 4px">${Math.round(zoom*100)}%</b><button class="btn2" onclick="setZoom(0.1)">Plus</button><button class="btn2" onclick="fitChart()">Fit to screen</button></div></div><button class="btn2" onclick="document.querySelector('#chartOverlay').remove()">Close</button></div><div class="chartBody" id="chartBody"><div class="orgwrap" id="orgwrap" style="transform:scale(${zoom})">${node(root)}</div></div>`;document.body.appendChild(ov)}
function setZoom(d){window._chartZoom=Math.min(1.4,Math.max(0.4,(window._chartZoom||0.82)+d));const w=document.querySelector('#orgwrap');if(w)w.style.transform=`scale(${window._chartZoom})`;const ov=document.querySelector('#chartOverlay');if(ov){const b=ov.querySelector('.chartTop b b');}openChartRefresh()}
function openChartRefresh(){const ov=document.querySelector('#chartOverlay');if(!ov)return;const pct=ov.querySelector('.chartTop .tabs b');if(pct)pct.textContent=Math.round((window._chartZoom||0.82)*100)+'%'}
function fitChart(){const body=document.querySelector('#chartBody');const w=document.querySelector('#orgwrap');if(!body||!w)return;const prev=w.style.transform;w.style.transform='scale(1)';const need=w.scrollWidth||1200;const avail=body.clientWidth-30;window._chartZoom=Math.min(1,Math.max(0.35,avail/need));w.style.transform=`scale(${window._chartZoom})`;openChartRefresh();body.scrollTo({left:0,top:0})}
